/**
 * Delivery pump: dequeue → skip duplicates → process → ack + emit, or requeue
 * with backoff on failure.
 *
 * How the guarantees hold under any failure/retry/clock combination:
 * - Effectively-once: the sink is told about a delivery only AFTER
 *   processMessage reported success, so a retry that follows a spurious
 *   failure ("the downstream already accepted but the pump reported failure")
 *   can never emit the same id a second time — the failed attempt goes back to
 *   the queue and only the eventually-successful attempt is emitted, exactly
 *   once. An attempt that keeps failing is abandoned after maxAttempts and
 *   reported through sink.failed instead of ever being emitted again. A throw
 *   from processMessage counts as a failed attempt, so no failure mode can
 *   bypass the retry path and lose or duplicate a message.
 * - Per-key ordering: a failed message is requeued at the HEAD of the queue,
 *   keeping it ahead of every message enqueued after it. While it waits for
 *   its retry (retryAt in the future) the pump steps over it, but no message
 *   sharing its key may pass it. No message sharing its id may pass it either,
 *   so a duplicate copy can never be delivered while the original attempt is
 *   still unresolved. Only messages with a different id and a different key
 *   may proceed past a waiting message.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const retrier = retryWithBackoff(clock)

  // Pull the next message that may be delivered right now: the oldest pending
  // entry that is due and not blocked by an earlier message waiting for a
  // retry. Every entry stepped over (not due, or blocked itself) blocks its
  // own id and key for the rest of the scan. Stepped-over entries are put back
  // in their original relative order (requeue inserts at the head, so restore
  // in reverse).
  function takeDeliverable() {
    const blockedIds = new Set()
    const blockedKeys = new Set()
    const steppedOver = []
    let chosen = null
    for (;;) {
      const message = queue.dequeue()
      if (message === null) break
      const now = clock.now()
      const due = message.retryAt === undefined || now >= message.retryAt
      const clear = !blockedIds.has(message.id) && !blockedKeys.has(message.key)
      if (due && clear) {
        chosen = message
        break
      }
      blockedIds.add(message.id)
      blockedKeys.add(message.key)
      steppedOver.push(message)
    }
    for (let i = steppedOver.length - 1; i >= 0; i--) queue.requeue(steppedOver[i])
    return chosen
  }

  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const message = takeDeliverable()
        if (message === null) break
        if (dedup.isDuplicate(message.id, clock.now())) {
          queue.ack(message.id)
          continue
        }
        let ok = false
        try {
          ok = processMessage(message)
        } catch {
          ok = false
        }
        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
          } else {
            message.retryAt = retrier.scheduleRetry(message.attempts, clock.now())
            queue.requeue(message)
          }
          continue
        }
        queue.ack(message.id)
        sink.emit(message)
        dedup.record(message.id, clock.now())
      }
    },
  }
}

