import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

function makeClock(start = 0) {
  let t = start
  return {
    now: () => t,
    advance: (ms) => { t += ms; return t },
  }
}

// 1. Headline scenario: downstream accepted but the pump reported failure.
{
  const clock = makeClock()
  const queue = createQueue()
  const sink = createSink()
  const downstream = []
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 1000 }),
    processMessage: (m) => {
      downstream.push(m.id) // downstream accepts...
      return downstream.length > 1 // ...but the pump reports failure the first time
    },
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), [], 'failed attempt must not emit')
  assert.deepEqual(queue.pending().map((m) => m.id), ['m1'], 'message waits for retry')
  clock.advance(100)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'], 'delivered exactly once after retry')
  assert.equal(sink.hasDuplicate(), false)
  assert.deepEqual(sink.failedIds(), [])
  clock.advance(100000)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'], 'still exactly once after clock runs away')
  console.log('1. ambiguous failure: no duplicate  ✓')
}

// 2. Permanently failing message: abandoned after maxAttempts, never delivered.
{
  const clock = makeClock()
  const queue = createQueue()
  const sink = createSink()
  let calls = 0
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 1000 }),
    processMessage: () => { calls++; return false },
    maxAttempts: 3,
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  for (let i = 0; i < 50 && queue.pending().length > 0; i++) {
    pump.run(10)
    clock.advance(5000)
  }
  assert.deepEqual(sink.deliveredIds(), [], 'never emitted')
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.equal(calls, 3, 'exactly maxAttempts downstream calls')
  assert.equal(queue.pending().length, 0)
  assert.equal(sink.hasDuplicate(), false)
  console.log('2. exhausted retries: failed, not duplicated  ✓')
}

// 3. Per-key order across retries: successor must not pass a waiting message.
{
  const clock = makeClock()
  const queue = createQueue()
  const sink = createSink()
  const seen = new Map()
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 1000 }),
    processMessage: (m) => {
      const n = seen.get(m.id) ?? 0
      seen.set(m.id, n + 1)
      return m.id !== 'm1' || n >= 1 // m1 fails on its first attempt
    },
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), [], 'same-key successor must wait behind the retrying message')
  clock.advance(100)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'], 'order preserved across the retry')
  assert.equal(sink.hasDuplicate(), false)
  console.log('3. per-key order across retry  ✓')
}

// 4. Duplicate id arriving while the original is mid-retry (head-of-queue).
{
  const clock = makeClock()
  const queue = createQueue()
  const sink = createSink()
  const seen = new Map()
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 1000 }),
    processMessage: (m) => {
      const n = seen.get(m.id) ?? 0
      seen.set(m.id, n + 1)
      if (m.id === 'm1') return n >= 1
      return true
    },
  })
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K2', payload: 2 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2'], 'unrelated key proceeds during backoff')
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 }) // duplicate arrives mid-flight
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2'], 'duplicate of unresolved id not delivered')
  clock.advance(100)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2', 'm1'], 'original delivered after retry')
  clock.advance(100000)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m2', 'm1'], 'still exactly once')
  assert.equal(sink.hasDuplicate(), false)
  console.log('4. duplicate id behind unresolved attempt  ✓')
}

// 5. Clock jumps: backward jump must not fire the retry early; huge forward
//    jump fires it immediately; dedup window expiry must not resurrect ids.
{
  const clock = makeClock(1000)
  const queue = createQueue()
  const sink = createSink()
  const seen = new Map()
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 50 }),
    processMessage: (m) => {
      const n = seen.get(m.id) ?? 0
      seen.set(m.id, n + 1)
      return m.id !== 'm1' || n >= 1
    },
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  pump.run(10) // m1 fails at t=1000, retryAt=1100
  clock.advance(-100) // backward jump to 900
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), [], 'backward clock must not deliver early')
  clock.advance(199) // 1099 — still one tick short
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), [], 'retry not due before retryAt')
  clock.advance(1) // exactly retryAt
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'], 'due exactly at retryAt, in order')
  clock.advance(100000)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'], 'window expiry changes nothing')
  assert.equal(sink.hasDuplicate(), false)
  console.log('5. backward/forward clock jumps  ✓')
}

// 6. processMessage throwing (accepted, then blew up) counts as a failure.
{
  const clock = makeClock()
  const queue = createQueue()
  const sink = createSink()
  let calls = 0
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 1000 }),
    processMessage: () => {
      calls++
      if (calls === 1) throw new Error('connection reset after send')
      return true
    },
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), [], 'throwing attempt must not emit')
  clock.advance(100)
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  console.log('6. throw treated as failed attempt  ✓')
}

// 7. run(steps) processes at most `steps` messages.
{
  const clock = makeClock()
  const queue = createQueue()
  const sink = createSink()
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 1000 }),
    processMessage: () => true,
  })
  for (let i = 0; i < 5; i++) queue.enqueue({ id: 'm' + i, key: 'K' + i, payload: i })
  pump.run(2)
  assert.equal(sink.deliveredIds().length, 2)
  pump.run()
  assert.equal(sink.deliveredIds().length, 5)
  assert.equal(sink.hasDuplicate(), false)
  console.log('7. step budget respected  ✓')
}

// 8. First message of a key abandoned → successors still delivered, order kept.
{
  const clock = makeClock()
  const queue = createQueue()
  const sink = createSink()
  const pump = createPump({
    queue, sink, clock,
    dedup: createDedup({ windowMs: 1000 }),
    processMessage: (m) => m.id !== 'm1',
    maxAttempts: 2,
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  for (let i = 0; i < 50 && queue.pending().length > 0; i++) {
    pump.run(10)
    clock.advance(500)
  }
  assert.deepEqual(sink.deliveredIds(), ['m2'], 'successor delivered after the original was abandoned')
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  console.log('8. abandoned head unblocks its key  ✓')
}

// 9. Seeded chaos: random failures/throws/duplicates/clock advances; the
//    invariants must hold at every observation point.
{
  let seed = 0x2f6e2b1
  const rand = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0
    return seed / 0x100000000
  }
  for (let trial = 0; trial < 200; trial++) {
    const clock = makeClock()
    const queue = createQueue()
    const sink = createSink()
    const N = 12
    const KEYS = 4
    const firstEnqueuePos = new Map()
    const outcome = new Map() // id -> [false|'throw'|true, ...] then always true
    for (let i = 0; i < N; i++) {
      const id = 'm' + i
      firstEnqueuePos.set(id, i)
      const script = []
      const rolls = Math.floor(rand() * 3)
      for (let r = 0; r < rolls; r++) script.push(rand() < 0.5 ? false : 'throw')
      script.push(true)
      outcome.set(id, script)
    }
    const alwaysFail = rand() < 0.3
    const attemptsOf = new Map()
    const pump = createPump({
      queue, sink, clock,
      dedup: createDedup({ windowMs: 20 + Math.floor(rand() * 200) }),
      processMessage: (m) => {
        if (rand() < 0.05) clock.advance(Math.floor(rand() * 300)) // clock moves inside the call
        const n = attemptsOf.get(m.id) ?? 0
        attemptsOf.set(m.id, n + 1)
        if (alwaysFail && m.id === 'm3') return false
        const script = outcome.get(m.id)
        const step = script[Math.min(n, script.length - 1)]
        return step === 'throw' ? (() => { throw new Error('boom ' + m.id) })() : step
      },
    })
    for (let i = 0; i < N; i++) queue.enqueue({ id: 'm' + i, key: 'K' + (i % KEYS), payload: i })
    const deliveredSnapshot = () => sink.deliveredIds()
    const check = () => {
      const ids = deliveredSnapshot()
      assert.equal(sink.hasDuplicate(), false, 'duplicate delivery (trial ' + trial + ')')
      assert.equal(new Set(ids).size, ids.length, 'dup ids in stream (trial ' + trial + ')')
      const best = new Map()
      for (const id of ids) {
        const pos = firstEnqueuePos.get(id)
        const key = 'K' + (pos % KEYS)
        const prev = best.get(key)
        if (prev !== undefined) assert.ok(pos > prev, 'per-key inversion at ' + id + ' (trial ' + trial + ')')
        best.set(key, pos)
      }
      const failed = new Set(sink.failedIds())
      for (const id of ids) assert.ok(!failed.has(id), 'id both delivered and failed (trial ' + trial + ')')
    }
    for (let round = 0; round < 400; round++) {
      if (rand() < 0.7) clock.advance(Math.floor(rand() * 250))
      pump.run(1 + Math.floor(rand() * 6))
      if (rand() < 0.15) {
        const dupOf = 'm' + Math.floor(rand() * N)
        queue.enqueue({ id: dupOf, key: 'K' + (Number(dupOf.slice(1)) % KEYS), payload: 'dup' })
      }
      check()
      const resolved = sink.deliveredIds().length + sink.failedIds().length
      if (resolved >= N + 4 && queue.pending().length === 0) break
    }
    check()
  }
  console.log('9. chaos (200 seeded trials): effectively-once + per-key order  ✓')
}

console.log('ALL GUARANTEE CHECKS PASSED')
